mapper.select:
select  
order by a.achievement_date desc, a.achievement_id desc
limit #{criteria.pageSize} offset #{criteria.page} * #{criteria.pageSize}

mapper.update:
update degree_completion_achievements set management_item_code = #{managementItemCode},
  achievement_date = #{occurredDate}, achievement_status = #{certificationStatus},
  detail_payload = cast(#{achievementDetail} as jsonb), attachment_count = #{attachmentCount},
  occurrence_date_warning_yn = case when #{occurrenceDateWarning} then 'Y' else 'N' end,
  updated_at = current_timestamp, updated_by = #{teacherUserId}
where achievement_id = #{achievementId}

mapper.select:
select exists (select 1 from input_period_settings where evaluation_year = #{evaluationYear}
  and organization_code = #{organizationCode} and area_code = 'EDUCATION' and active_yn = 'Y'
  and #{checkedAt} between start_at and end_at)

select exists (select 1 from evaluation_date_settings where evaluation_year = #{evaluationYear}
  and organization_code = #{organizationCode} and area_code = 'EDUCATION' and active_yn = 'Y'
  and #{occurrenceDate} between start_at::date and end_at::date)
